<?php
declare(strict_types=1);require_once __DIR__.'/board-report.php';
const STOCK_SIZES=['XS','S','M','L','XL','2XL','3XL','4XL'];
function stock_matrix_schema(PDO $db):void {stock_schema($db);$db->exec("CREATE TABLE IF NOT EXISTS stock_batches(id INTEGER PRIMARY KEY AUTOINCREMENT,request_key TEXT UNIQUE NOT NULL,sku TEXT NOT NULL,kind TEXT NOT NULL,quantities TEXT NOT NULL,note TEXT NOT NULL,revision INTEGER NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS stock_batch_edits(id INTEGER PRIMARY KEY AUTOINCREMENT,batch_id INTEGER NOT NULL,before_data TEXT NOT NULL,after_data TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS stock_matrix_requests(request_key TEXT PRIMARY KEY,payload TEXT NOT NULL,result TEXT NOT NULL)");}
function stock_matrix(PDO $db):array {team_require_owner();stock_matrix_schema($db);$data=stock_view($db);$data['batches']=$db->query('SELECT * FROM stock_batches ORDER BY id DESC LIMIT 200')->fetchAll();foreach($data['batches'] as &$b)$b['quantities']=json_decode($b['quantities'],true,512,JSON_THROW_ON_ERROR);unset($b);$data['revisions']=$db->query('SELECT batch_id,before_data,after_data,actor,created_at FROM stock_batch_edits ORDER BY id DESC LIMIT 200')->fetchAll();$data['token']=hash('sha256',json_encode([$data['balances'],$data['version']],JSON_UNESCAPED_UNICODE));return $data;}
function stock_matrix_save(PDO $db,array $input,array $user):array {
 team_require_owner();stock_matrix_schema($db);$key=(string)($input['request_key']??'');$sku=mb_strtoupper(trim((string)($input['sku']??'')),'UTF-8');$kind=$input['kind']??'';$note=trim((string)($input['note']??''));$quantities=$input['quantities']??null;$id=(int)($input['id']??0);if(!preg_match('/^[a-f0-9-]{36}$/D',$key)||!preg_match('/^[A-Z0-9][A-Z0-9._-]{0,39}$/D',$sku)||!in_array($kind,['receipt','return','stocktake'],true)||!is_array($quantities)||mb_strlen($note)>1000)throw new RuntimeException('Kiểm tra mã, số lượng và ghi chú.',400);$values=[];foreach($quantities as $size=>$qty){if(!in_array($size,STOCK_SIZES,true)||!is_int($qty)||$qty<0||$qty>1000000)throw new RuntimeException('Số lượng theo size phải là số nguyên từ 0.',400);$values[$size]=$qty;}if(!$values)throw new RuntimeException('Nhập ít nhất một size. Ô trống được giữ nguyên.',400);ksort($values);$payload=json_encode([$id,$sku,$kind,$values,$note,(int)($input['revision']??0)],JSON_UNESCAPED_UNICODE);
 $db->exec('BEGIN IMMEDIATE');try{$q=$db->prepare('SELECT * FROM stock_matrix_requests WHERE request_key=?');$q->execute([$key]);if($prior=$q->fetch()){if($prior['payload']!==$payload)throw new RuntimeException('Yêu cầu đã dùng cho dữ liệu khác. Thử lại.',409);$db->exec('COMMIT');return json_decode($prior['result'],true);}$old=null;if($id){$q=$db->prepare('SELECT * FROM stock_batches WHERE id=?');$q->execute([$id]);$old=$q->fetch();if(!$old||(int)$old['revision']!==(int)($input['revision']??0))throw new RuntimeException('Phiếu vừa được sửa. Tải lại trước khi thay đổi.',409);if($old['sku']!==$sku||$old['kind']!==$kind||$kind==='stocktake')throw new RuntimeException('Chỉ sửa số lượng / ghi chú của phiếu nhập hoặc hoàn; điều chỉnh tồn bằng phiếu kiểm kê mới.',400);}
 $catalog=board_catalog($db);if(!isset($catalog[$sku])){$gender=$input['gender']??'';if(!in_array($gender,['Nam','Nữ'],true))throw new RuntimeException('Chọn nhóm cho mã mới.',400);$db->prepare('INSERT INTO stock_products VALUES(?,?,?)')->execute([$sku,$sku,$gender]);}
 $before=$old?json_decode($old['quantities'],true):[];$deltas=[];if($kind==='stocktake'){$current=stock_matrix($db);if(!hash_equals($current['token'],(string)($input['token']??'')))throw new RuntimeException('Tồn kho vừa thay đổi. Làm mới và kiểm tra trước khi đặt tồn.',409);$balances=[];foreach($current['balances'] as $b)if($b['sku']===$sku)$balances[$b['size']]=$b['balance'];foreach($values as $size=>$qty)$deltas[$size]=$qty-($balances[$size]??0);}else foreach(array_unique(array_merge(array_keys($values),array_keys($before))) as $size)$deltas[$size]=($values[$size]??0)-($before[$size]??0);
 $now=gmdate('c');if($old){$db->prepare('UPDATE stock_batches SET quantities=?,note=?,revision=revision+1,updated_at=? WHERE id=?')->execute([json_encode($values),$note,$now,$id]);$db->prepare('INSERT INTO stock_batch_edits(batch_id,before_data,after_data,actor,created_at) VALUES(?,?,?,?,?)')->execute([$id,json_encode($old,JSON_UNESCAPED_UNICODE),json_encode(['quantities'=>$values,'note'=>$note],JSON_UNESCAPED_UNICODE),$user['username'],$now]);}else{$db->prepare('INSERT INTO stock_batches(request_key,sku,kind,quantities,note,revision,actor,created_at,updated_at) VALUES(?,?,?,?,?,1,?,?,?)')->execute([$key,$sku,$kind,json_encode($values),$note,$user['username'],$now,$now]);$id=(int)$db->lastInsertId();}
 $save=$db->prepare('INSERT INTO stock_movements(request_key,sku,size,kind,quantity,note,actor,created_at) VALUES(?,?,?,?,?,?,?,?)');foreach($deltas as $size=>$delta)if($delta!==0)$save->execute([$key.':'.$size,$sku,$size,$kind==='stocktake'?'adjust':$kind,$delta,'Phiếu #'.$id.($old?' · Điều chỉnh':'').' · '.$note,$user['username'],$now]);$result=['ok'=>true,'id'=>$id];$db->prepare('INSERT INTO stock_matrix_requests VALUES(?,?,?)')->execute([$key,$payload,json_encode($result)]);people_audit('stock_matrix',$sku,['batch'=>$id,'kind'=>$kind,'before'=>$before,'after'=>$values,'deltas'=>$deltas,'note'=>$note],$db);$db->exec('COMMIT');return $result;
 }catch(Throwable $e){$db->exec('ROLLBACK');throw $e;}
}
